  "서비스를 다시 시작하려면 sudo가 필요해요. 이 SSH 사용자에게 비밀번호 없는 sudo(sudo -n)를 허용하거나, 서버에서 직접 업데이트해 주세요.": "Restarting the service needs sudo. Allow passwordless sudo (sudo -n) for this SSH user, or update on the server yourself.",
  "Arkism 서버를 돌리는 systemd 서비스를 찾지 못했어요. 서버를 서비스로 띄운 뒤 다시 시도하거나, 직접 업데이트해 주세요.": "Could not find a systemd service running the Arkism server. Run the server as a service and try again, or update it yourself.",
  "서버 묶음 안의 파일이 예상과 달라 설치하지 않았어요.": "The files in the server package were not the expected ones, so nothing was installed.",
  "새 서버가 정상으로 뜨지 않아 예전 버전으로 되돌렸어요. DB 구조 변경이 필요하면 서버에서 memoryd --init-db를 먼저 실행하세요.": "The new server did not come up, so the previous version was restored. If the database schema must change, run memoryd --init-db on the server first.",
  "새 서버가 뜨지 않았고 되돌리기도 실패했어요. 서버의 설치 폴더 .backup-* 에서 직접 되돌려 주세요.": "The new server did not come up and restoring failed too. Restore it yourself from .backup-* in the server's install folder.",
