  "이 기억과 근거가 된 원본 기록을 영구히 지워요. 같은 원본에서 나온 다른 기억도 함께 지워져요.": "Permanently erases this memory and the source records behind it. Other memories from the same sources are erased too.",
  "영구 삭제": "Erase permanently",
  "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "Enter what you want gone, like a person's name or an email address. Arkism finds every memory and source record containing it and erases them permanently. You see the count first.",
