  "시작 노드에는 선을 이을 수 없어요.": "Lines can't connect into the start node.",
  "되돌아가는 선이에요. 최대 2번까지 다시 돌아요. 선을 눌러 횟수와 갈래 이름을 바꿀 수 있어요.": "This is a loop-back line. It repeats up to 2 times. Click the line to change the count and branch name.",
  "노드마다": "Per node",
  "없어요": "None",
  "워크플로우 설정": "Workflow settings",
  "노드 설정": "Node settings",
  "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Click a node to edit it here. Drag an output dot to connect to the next node; connecting to an earlier node makes a loop-back line. Click a line to open its settings. Scroll to zoom; middle-click drag or hold Space and drag to pan.",
  "노드": "Node",
  "되돌아가는 선": "Loop-back line",
  "고르세요": "Choose",
  "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "If the output is {\"ok\": true/false, …}, it splits into pass and fail branches. The first run takes 1–2 seconds to build and must finish within 30 seconds. Uses no tokens.",
  "배포·게시처럼 되돌릴 수 없는 단계 바로 앞에 두세요. 답이 올 때까지 멈춰요.": "Place it right before irreversible steps like deploys or publishing. It pauses until there's an answer.",
