  "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Sets of colors, fonts and rules for apps, email, web and docs. Pick one to see the details on the right.",
  "슬라이드 프롬프트": "Slide prompts",
  "변수 값을 채우고 바로 만들거나, ComfyUI 워크플로우로 보내요.": "Fill in the variables and make it right away, or send it to a ComfyUI workflow.",
  "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Slide prompts for talks and reports, plus the scripts that make them. Pick a card to edit it on the right and make it right away.",
  "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Your go-to image prompts with example images. Filter by model and category.",
  "플러그인은 스킬 + MCP + 명령을 한 번에 설치하는 묶음이에요.": "A plugin installs skills, MCP servers and commands together in one bundle.",
