  "의도별": "By intent",
  "순서대로": "In order",
  "의도별: 자동 라우팅이 켜져 있고 판정 모델이 있으면 판정 모델이 요청 내용과 모델 설명을 보고 그룹 안에서 골라요. 아니면 1번 모델로 가요.": "By intent: with auto routing on and a judge model set, the judge model reads the request and the model descriptions and picks within the group. Otherwise requests go to model 1.",
  "순서대로: 늘 1번 모델로 보내고, 실패하면 다음 모델로 넘겨요.": "In order: always sends to model 1 and moves to the next one if it fails.",
